/* TRM Workspace — accessible, RTL, server-backed client. No candidate PII persisted locally. */
'use strict';
const $=(s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>Array.from(root.querySelectorAll(s));
const safe=(v='')=>String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const dname=(s)=>({identified:'شناسایی‌شده',contacted:'تماس اولیه',interested:'علاقه‌مند',nurturing:'در ارتباط',opportunity:'فرصت شغلی',selection:'در ارزیابی',hired:'استخدام‌شده',declined:'منصرف',archived:'بایگانی',direct:'شناسایی مستقیم',referral:'معرفی همکار',alumni:'همکار سابق',internship:'کارآموزی',campus:'دانشگاه',community:'جامعه حرفه‌ای',scouting:'استعدادیابی',event:'رویداد',other:'سایر',unknown:'نامشخص',granted:'اجازه داده',revoked:'لغو اجازه',owner:'مالک',admin:'مدیر',recruiter:'کارشناس جذب',manager:'مدیر صف',viewer:'مشاهده‌گر',call:'تماس',email:'ایمیل',meeting:'جلسه',followup:'پیگیری',note:'یادداشت',selection:'ارزیابی'})[s]||s||'—';
const fnum=n=>new Intl.NumberFormat('fa-IR').format(n||0);
const fdate=d=>{if(!d)return'—';const v=new Date(String(d).slice(0,10)+'T12:00:00');return isNaN(v)?safe(d):new Intl.DateTimeFormat('fa-IR',{year:'numeric',month:'short',day:'numeric'}).format(v)};
const today=()=>new Date().toISOString().slice(0,10);
const ICON={dashboard:'◈',candidates:'♟',positions:'◉',groups:'◎',evp:'✦',sourcing:'⌁',relationships:'♡',experience:'✳',reports:'▥',settings:'⚙',help:'◌'};
const NAV=[['dashboard','خانه'],['candidates','استعدادها'],['positions','نقش‌های حیاتی'],['groups','گروه‌های هدف'],['evp','پیشنهاد ارزش'],['sourcing','منابع جذب'],['relationships','ارتباطات'],['experience','تجربه نامزد'],['reports','گزارش‌ها'],['settings','تنظیمات']];
let st={me:null,page:'dashboard',candidates:[],positions:[],groups:[],evps:[],activities:[],referrals:[],dashboard:null,members:[],audit:[],query:'',stage:'',priority:'',candidateTab:'activities',installPrompt:null,selectedCandidate:null,sourcePage:'dashboard',roi:{revenue:0,costs:0,hr:0,fte:0}};

async function api(path,method='GET',payload){
 const opts={method,credentials:'same-origin',headers:{'Accept':'application/json'}};
 if(payload!==undefined){opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(payload)}
 let r;try{r=await fetch('/api'+path,opts)}catch{throw new Error('ارتباط با سرور برقرار نشد. اینترنت را بررسی کنید.')}
 let data;try{data=await r.json()}catch{data={}}
 if(!r.ok){if(r.status===401&&st.me){st.me=null;renderPublic('login')}const e=new Error(typeof data.detail==='string'?data.detail:'در ثبت اطلاعات مشکلی پیش آمد.');e.status=r.status;throw e;}
 return data;
}
const node=$('#app');const modalRoot=$('#modal-root');
function toast(message,kind='ok'){const root=$('#toast-root');root.innerHTML=`<div class="toast">${kind==='error'?'⚠ ':'✓ '}${safe(message)}</div>`;setTimeout(()=>root.innerHTML='',4400)}
function openModal(title,body,opts={}){modalRoot.innerHTML=`<div class="modal ${opts.narrow?'narrow':''}" role="dialog" aria-modal="true"><div class="modal-head"><div><h2>${safe(title)}</h2>${opts.description?`<p class="muted">${safe(opts.description)}</p>`:''}</div><button class="x-btn" type="button" data-act="close-modal" aria-label="بستن">×</button></div>${body}</div>`;modalRoot.scrollTop=0}
function closeModal(){modalRoot.innerHTML=''}
function field(label,name,value='',type='text',extra=''){return `<div class="form-group"><label for="f-${safe(name)}">${safe(label)}</label><input id="f-${safe(name)}" name="${safe(name)}" type="${safe(type)}" value="${safe(value)}" ${extra}></div>`}
function area(label,name,value='',hint=''){return `<div class="form-group"><label for="f-${safe(name)}">${safe(label)}</label><textarea id="f-${safe(name)}" name="${safe(name)}">${safe(value)}</textarea>${hint?`<small class="field-help">${safe(hint)}</small>`:''}</div>`}
function selectField(label,name,current,opts,placeholder='انتخاب کنید'){return `<div class="form-group"><label>${safe(label)}</label><select name="${safe(name)}">${placeholder?`<option value="">${safe(placeholder)}</option>`:''}${opts.map(o=>{const [value,txt]=Array.isArray(o)?o:[o,dname(o)];return `<option value="${safe(value)}" ${String(value)===String(current)?'selected':''}>${safe(txt)}</option>`}).join('')}</select></div>`}
function formFooter(label='ذخیره اطلاعات'){return `<div class="modal-footer"><button class="btn secondary" type="button" data-act="close-modal">انصراف</button><button class="btn" type="submit">${safe(label)}</button></div>`}
function publicHeader(){return `<header class="public-head"><div class="brand"><span class="brandmark">✳</span><div>مدیریت روابط با استعداد<div class="brand-english">TRM WORKSPACE</div></div></div><div class="buttons"><button class="btn secondary small" data-act="switch-auth" data-target="login">ورود</button><button class="btn small" data-act="switch-auth" data-target="register">شروع سازمانی</button></div></header>`}
function art(){return `<div class="network-art" aria-hidden="true"><div class="art-label">از ارتباط، مزیت رقابتی بسازید</div><svg viewBox="0 0 600 470"><g fill="none" stroke="#e6ede5" opacity=".45" stroke-width="2"><path d="M300 105L147 220L290 350L465 205L300 105M147 220L465 205M290 350L300 105M465 205L485 335L290 350L115 365L147 220M115 365L300 105"/></g><g fill="#e8c38d"><circle cx="300" cy="105" r="37"/><circle cx="465" cy="205" r="27"/><circle cx="290" cy="350" r="34"/></g><g fill="#b0e1d4"><circle cx="147" cy="220" r="28"/><circle cx="485" cy="335" r="20"/><circle cx="115" cy="365" r="20"/></g><g fill="#0e5b5e"><circle cx="300" cy="92" r="12"/><path d="M278 126Q300 103 322 126"/><circle cx="290" cy="339" r="11"/><path d="M270 366Q290 344 309 366"/></g></svg><div class="art-note">Talent-Focused · Relationship-Driven</div></div>`}
function renderPublic(view='landing'){
 st.me=null;document.title='TRM Workspace | مدیریت روابط با استعداد';
 const inviteCode=new URL(location.href).searchParams.get('invite');if(inviteCode&&view==='landing')view='invite';
 if(view==='landing'){
 node.innerHTML=`<div class="public">${publicHeader()}<main><section class="public-hero"><div><div class="eyebrow">TALENT RELATIONSHIP MANAGEMENT</div><h1>استعدادها را فقط پیدا نکنید؛<br><span>با آن‌ها رابطه بسازید.</span></h1><p class="lead">از شناسایی نقش‌های حیاتی تا ساخت Talent Pool، ارتباط‌های حرفه‌ای مستمر و تصمیم‌های دقیق جذب؛ همه در یک فضای مستقل برای سازمان شما.</p><div class="buttons"><button class="btn" data-act="switch-auth" data-target="register">ایجاد فضای سازمان ←</button><button class="btn secondary" data-act="switch-auth" data-target="login">ورود اعضای سازمان</button></div><div class="trustrow"><span class="chip">◉ داده‌های مستقل هر سازمان</span><span class="chip">✳ قابل نصب روی گوشی</span><span class="chip">♡ مدیریت ارتباط بلندمدت</span></div></div>${art()}</section><section class="public-features"><div class="feature"><span>◉</span><b>نقشه نقش‌های حیاتی</b><p class="muted">نقش‌های کلیدی و گلوگاهی را شناسایی کنید و منابع جذب را به اولویت واقعی کسب‌وکار متصل کنید.</p></div><div class="feature"><span>♡</span><b>پرونده و چرخه ارتباط</b><p class="muted">هر استعداد یک پرونده، تاریخچه تعامل، مالک رابطه و اقدام بعدی مشخص داشته باشد.</p></div><div class="feature"><span>◈</span><b>دید مدیریتی و پاسخگویی</b><p class="muted">پیگیری‌های معوق، سلامت Talent Pool و عملکرد کانال‌های جذب را از داده واقعی ببینید.</p></div></section></main><footer class="center muted" style="padding:24px">رویکرد الهام‌گرفته از مدل علمی Armin Trost (2014) · محصول اجرایی مستقل</footer></div>`;
 } else if(view==='login'||view==='register'){
 const reg=view==='register';node.innerHTML=`<div class="public">${publicHeader()}<main class="auth-layout"><div class="auth-card"><div class="eyebrow">${reg?'CREATE WORKSPACE':'WELCOME BACK'}</div><h2>${reg?'فضای مستقل سازمان خود را بسازید':'ورود به فضای سازمان'}</h2><p class="muted">${reg?'اطلاعات هر سازمان در فضایی مجزا نگهداری می‌شود.':'با ایمیل و رمز عبور وارد شوید.'}</p><form data-form="${reg?'register':'login'}">${reg?field('نام سازمان','org_name','','text','required minlength="2"')+field('نام و نام خانوادگی','name','','text','required minlength="2"'):''}${field('ایمیل کاری','email','','email','required autocomplete="email"')}${field('رمز عبور'+(reg?' (حداقل ۱۰ کاراکتر)':''),'password','','password',`required ${reg?'minlength="10"':'autocomplete="current-password"'}`)}<button class="btn" type="submit" style="width:100%">${reg?'ساخت فضای سازمان':'ورود به حساب'}</button></form><div class="center muted" style="margin-top:18px">${reg?'قبلاً حساب ساخته‌اید؟':'هنوز فضای سازمانی ندارید؟'} <a href="#" data-act="switch-auth" data-target="${reg?'login':'register'}" style="color:var(--teal);font-weight:800">${reg?'ورود':'شروع رایگان'}</a></div></div><div class="center" style="padding:20px"><button class="btn ghost small" data-act="switch-auth" data-target="landing">بازگشت به معرفی</button></div></main></div>`;
 } else if(view==='invite'){
 const code=new URL(location.href).searchParams.get('invite')||'';
 node.innerHTML=`<div class="public">${publicHeader()}<main class="auth-layout"><div class="auth-card"><div class="eyebrow">TEAM INVITATION</div><h2>پیوستن به فضای سازمان</h2><p id="invite-info" class="muted">در حال بررسی دعوت‌نامه…</p><form data-form="accept-invite"><input type="hidden" name="code" value="${safe(code)}">${field('نام و نام خانوادگی','name','','text','required minlength="2"')}${field('رمز عبور جدید (حداقل ۱۰ کاراکتر)','password','','password','required minlength="10"')}<button class="btn" type="submit" style="width:100%">پذیرش دعوت و ورود</button></form></div></main></div>`;
 api('/invites/preview/'+encodeURIComponent(code)).then(x=>{$('#invite-info').innerHTML=`شما با ایمیل <b class="ltr">${safe(x.email)}</b> به سازمان <b>${safe(x.org)}</b> دعوت شده‌اید.`}).catch(e=>{$('#invite-info').textContent=e.message;$('form[data-form="accept-invite"]').remove()});
 }
}
function appSidebar(){return `<aside class="sidebar"><div class="brand"><span class="brandmark">✳</span><div>مدیریت روابط با استعداد<div class="brand-english">TRM WORKSPACE</div></div></div><nav class="sidebar-nav"><div class="nav-section">فضای کار</div>${NAV.map(([id,label],i)=>`${i===4?'<div class="nav-section">راهبرد و مدیریت</div>':''}<a href="#${id}" class="nav-item ${st.page===id?'active':''}" data-nav="${id}"><span class="ico">${ICON[id]}</span>${label}</a>`).join('')}</nav><div class="sidebar-foot"><div class="muted" style="font-size:.79rem">فضای سازمان</div><b>${safe(st.me.org.name)}</b><div class="hairline" style="margin:12px 0"></div><button class="btn secondary small" style="width:100%" data-act="install">⬇ نصب اپلیکیشن</button></div></aside>`}
function topbar(){return `<header class="topbar"><div class="org-breadcrumb"><span>✳</span><b class="header-info">${safe(st.me.org.name)}</b><span> / </span><span>${safe(NAV.find(x=>x[0]===st.page)?.[1]||'خانه')}</span></div><div class="buttons"><button class="btn secondary small mobile-hide" data-act="install">⬇ نصب اپ</button><div class="user-pill"><div class="avatar">${safe(st.me.user.name.slice(0,1))}</div><div class="user-desc"><b style="font-size:.82rem">${safe(st.me.user.name)}</b><div class="muted" style="font-size:.7rem">${dname(st.me.user.role)}</div></div></div></div></header>`}
function mobileNav(){return `<nav class="bottom-nav">${[['dashboard','خانه'],['candidates','استعدادها'],['positions','نقش‌ها'],['relationships','پیگیری'],['settings','بیشتر']].map(([id,label])=>`<button class="${st.page===id?'active':''}" data-nav="${id}"><span class="bico">${ICON[id]}</span>${label}</button>`).join('')}</nav>`}
function pageHeader(title,sub,action=''){return `<div class="page-head"><div><h1>${safe(title)}</h1><p class="sub">${safe(sub)}</p></div>${action}</div>`}
function nbtn(act,text,id='',variant=''){return `<button class="btn ${variant}" data-act="${act}" ${id?`data-id="${safe(id)}"`:''}>${text}</button>`}
function empty(icon,title,body,action=''){return `<div class="empty"><div class="empty-ico">${icon}</div><h3>${safe(title)}</h3><p>${safe(body)}</p>${action}</div>`}
function dashboardPage(){const d=st.dashboard||{total:0,priority_a:0,overdue:0,due_soon:0,positions:0,stages:{},upcoming:[]};
 const tiles=[['candidates','استعدادها','پرونده‌ها و Talent Pool'],['positions','نقش‌های حیاتی','اولویت‌های استراتژیک'],['relationships','برنامه ارتباطات','گفتگوها و پیگیری‌ها'],['sourcing','جذب و تجربه نامزد','معرفی‌ها و کانال‌ها'],['reports','داشبورد مدیریتی','تصمیم‌گیری مبتنی بر داده']];
 return `<section class="hero-board"><div><div class="eyebrow">RELATIONSHIP FIRST, RECRUITMENT FOLLOWS</div><h1>رابطه‌های حرفه‌ای امروز،<br>سرمایه انسانی فردای سازمان</h1><p>${safe(st.me.org.name)} · هر استعداد یک ارتباط ارزشمند است؛ قدم بعدی را فراموش نکنید.</p>${nbtn('new-candidate','＋ افزودن اولین / استعداد جدید')}</div><div class="rings"><div class="ring-dot one"></div><div class="ring-dot two"></div><div class="ring-dot three"></div><div class="ring-center">✳</div></div></section>
 <div class="grid four" style="margin-bottom:22px"><div class="panel metric"><small>استعدادهای فعال</small><strong>${fnum(d.total)}</strong><small>پرونده موجود</small></div><div class="panel metric"><small>اولویت A</small><strong>${fnum(d.priority_a)}</strong><small>با تشخیص و شواهد تیم</small></div><div class="panel metric"><small>پیگیری معوق</small><strong style="color:${d.overdue?'#a9533d':'var(--teal)'}">${fnum(d.overdue)}</strong><small>نیازمند اقدام</small></div><div class="panel metric"><small>نقش‌های ثبت‌شده</small><strong>${fnum(d.positions)}</strong><small>برای برنامه‌ریزی جذب</small></div></div>
 <div class="grid tile-grid" style="grid-template-columns:repeat(auto-fit,minmax(190px,1fr));margin-bottom:22px">${tiles.map(([id,t,s])=>`<article class="panel feature-tile" role="button" tabindex="0" data-nav="${id}"><span class="tile-icon">${ICON[id]}</span><span class="tile-arrow">↖</span><div><h3>${t}</h3><p>${s}</p></div></article>`).join('')}</div>
 <div class="grid two"><section class="panel"><div class="panel-head"><div><h2>اقدام‌های پیش رو</h2><p class="sub">در هفت روز آینده و کارهای عقب‌افتاده</p></div><button class="btn secondary small" data-nav="relationships">همه پیگیری‌ها</button></div>${d.upcoming?.length?d.upcoming.map(a=>`<div class="detail-item separate"><div><b>${safe(a.name)}</b><p class="muted" style="font-size:.83rem">${safe(a.summary)}</p></div><span class="chip ${a.overdue?'warn':''}">${fdate(a.due_date)}</span></div>`).join(''):empty('♡','فعلاً اقدام زمان‌بندی‌شده ندارید','پس از ثبت استعداد، یک ارتباط یا پیگیری برای او تنظیم کنید.')}</section><section class="panel"><div class="panel-head"><div><h2>مسیر استعدادها</h2><p class="sub">توزیع واقعی پرونده‌ها در چرخه ارتباط</p></div></div>${d.total?stageBars(d.stages,d.total):empty('◈','نمودار هنوز داده ندارد','وقتی پرونده‌ها ثبت شوند، وضعیت حرکت استعدادها در اینجا دیده می‌شود.')}</section></div>`;
}
function stageBars(counts,total){return Object.entries(counts||{}).filter(([k,v])=>v>0).sort((a,b)=>b[1]-a[1]).map(([key,n])=>`<div class="barline"><label>${dname(key)}</label><div class="bar-track"><div class="bar-fill" style="width:${(n/(total||1))*100}%"></div></div><b>${fnum(n)}</b></div>`).join('')}
function candidatesPage(){const items=st.candidates.filter(c=>!c.archived&&(!st.query||[c.full_name,c.current_title,c.company,c.skills].some(x=>String(x||'').toLocaleLowerCase().includes(st.query.toLocaleLowerCase())))&&(!st.stage||c.stage===st.stage)&&(!st.priority||c.priority===st.priority));return pageHeader('استعدادها','Talent Pool سازمان؛ هر فرد، یک رابطه و یک اقدام بعدی',nbtn('new-candidate','＋ افزودن استعداد'))+`<div class="toolbar"><input class="grow" type="search" id="candidate-search" placeholder="جستجوی نام، تخصص یا شرکت…" value="${safe(st.query)}" aria-label="جستجوی استعداد"><select id="filter-stage"><option value="">همه مراحل</option>${['identified','contacted','interested','nurturing','opportunity','selection','hired','declined'].map(s=>`<option value="${s}" ${st.stage===s?'selected':''}>${dname(s)}</option>`).join('')}</select><select id="filter-priority"><option value="">همه اولویت‌ها</option>${['A','B','C'].map(s=>`<option value="${s}" ${st.priority===s?'selected':''}>اولویت ${s}</option>`).join('')}</select><button class="btn secondary small" data-act="import-csv">ورود CSV</button><button class="btn secondary small" data-act="export-csv">خروجی CSV</button></div><section class="records" id="candidate-records">${items.length?items.map(candidateRow).join(''):empty('♟','نتیجه‌ای پیدا نشد','هنوز پرونده‌ای ثبت نشده یا فیلترهای شما بیش از حد محدودند.',nbtn('new-candidate','＋ ثبت اولین استعداد'))}</section><p class="footnote">دسته‌بندی A/B/C فقط با معیارهای شغلی و شواهد قابل‌دفاع انجام شود؛ داده‌های حساس مبنای رتبه‌بندی نیستند.</p>`}
function candidateRow(c){return `<article class="record" data-act="view-candidate" data-id="${c.id}"><div class="avatar">${safe(c.full_name.slice(0,1))}</div><div class="info"><div class="meta"><strong>${safe(c.full_name)}</strong><span class="chip ${c.priority.toLowerCase()}">${safe(c.priority)}</span><span class="chip">${dname(c.stage)}</span>${c.do_not_contact?'<span class="chip warn">عدم تماس</span>':''}</div><p>${safe(c.current_title||'عنوان شغلی ثبت نشده')} ${c.company?' · '+safe(c.company):''}</p></div><span class="next ${c.next_followup&&c.next_followup<today()?'overdue':''}">${c.next_followup?'پیگیری: '+fdate(c.next_followup):'بدون پیگیری'}</span><span style="color:#71948c">‹</span></article>`}
function positionType(p){const key=p.strategic_importance>=4,bottle=p.market_availability<=2&&p.future_demand>=3;return key&&bottle?'کلیدی و گلوگاهی':key?'کلیدی':bottle?'گلوگاهی':'معمولی/در بررسی'}
function positionsPage(){const ps=st.positions;const matrix=`<div class="matrix" role="img" aria-label="پرتفوی نقش‌ها بر اساس اهمیت راهبردی و دسترسی به استعداد"><span class="matrix-axis-y">↑ دشواری تأمین استعداد</span><span class="matrix-axis-x">← اهمیت راهبردی بیشتر</span>${ps.map(p=>{const size=34+Math.min(40,Math.sqrt(p.future_demand||1)*9);const bottom=12+(6-p.market_availability)*14;const right=9+(p.strategic_importance-1)*17;return `<div class="matrix-dot ${p.strategic_importance>=4?'key':(p.market_availability<=2?'bottle':'')}" title="${safe(p.title)}" style="right:${right}%;bottom:${bottom}%;width:${size}px;height:${size}px" data-act="edit-position" data-id="${p.id}">${safe(p.title.length>12?p.title.slice(0,11)+'…':p.title)}</div>`}).join('')}</div>`;
 return pageHeader('نقش‌های حیاتی','برنامه‌ریزی جذب با تمرکز بر Key & Bottleneck Functions',nbtn('new-position','＋ تعریف نقش'))+`<div class="grid two"><section class="panel"><div class="panel-head"><h2>پرتفوی راهبردی نقش‌ها</h2><span class="chip">نمودار قابل کلیک</span></div>${ps.length?matrix:empty('◉','پرتفوی خالی است','اولین نقش را اضافه کنید تا اهمیت راهبردی و دشواری جذب روی نقشه قرار گیرد.')}<p class="footnote">اندازه دایره = تعداد نیروی موردنیاز آتی؛ طبقه‌بندی پیشنهادی بر پایه امتیازهای واردشده است، نه حکم قطعی.</p></section><section class="panel"><div class="panel-head"><h2>اولویت‌های سازمان</h2><span class="chip">${fnum(ps.length)} نقش</span></div>${ps.length?ps.map(p=>`<div class="detail-item separate"><div><b>${safe(p.title)}</b><p class="muted" style="font-size:.79rem">${safe(p.department||'واحد نامشخص')} · درخواست آینده: ${fnum(p.future_demand)} نفر</p><span class="chip ${positionType(p).includes('کلیدی')?'a':''}">${positionType(p)}</span></div><button class="btn secondary small" data-act="edit-position" data-id="${p.id}">بررسی</button></div>`).join(''):empty('◌','نقشی تعریف نشده است','از وظایف کلیدی کسب‌وکار شروع کنید.')}</section></div><section class="panel" style="margin-top:19px"><div class="panel-head"><h2>پرسش اصلی برای مدیرعامل</h2></div><div class="insight">اگر عملکرد افراد این نقش از متوسط به عالی برسد، آیا مزیت رقابتی سازمان به‌طور محسوس تقویت می‌شود؟ این سؤال با «آیا نقش ضروری است؟» متفاوت است.</div></section>`}
function groupsPage(){return pageHeader('گروه‌های هدف','چه کسانی در بازار کار می‌توانند نقش‌های کلیدی شما را پوشش دهند؟',nbtn('new-group','＋ گروه هدف'))+`<div class="grid three">${st.groups.length?st.groups.map(g=>`<div class="panel"><div class="eyebrow">TARGET SEGMENT</div><h3>${safe(g.name)}</h3><p class="muted" style="margin-top:8px;font-size:.88rem">${safe(g.traits||'ویژگی‌ها هنوز ثبت نشده‌اند.')}</p><div class="hairline"></div><p class="muted" style="font-size:.84rem">ترجیحات: ${safe(g.preferences||'—')}</p><button class="btn secondary small" style="margin-top:17px" data-act="edit-group" data-id="${g.id}">ویرایش گروه</button></div>`).join(''):empty('◎','اولین گروه هدف را تعریف کنید','مثلاً «کارشناسان باتجربه فروش فنی» یا «مهندسان با زمینه تحلیل داده».',nbtn('new-group','ایجاد گروه'))}</div>`}
function evpPage(){return pageHeader('پیشنهاد ارزش برای کارکنان','EVP باید واقعی، جذاب برای گروه هدف و متمایز از رقیب باشد.',nbtn('new-evp','＋ طراحی EVP'))+`<div class="insight" style="margin-bottom:21px"><strong>فرمول طراحی:</strong> قوت واقعی سازمان ∩ ترجیح گروه هدف ∩ وجه تمایز قابل دفاع → شواهد و تجربه‌های واقعی → پیام اختصاصی</div><div class="grid two">${st.evps.length?st.evps.map(e=>`<div class="panel"><div class="eyebrow">EMPLOYEE VALUE PROPOSITION</div><h3>${safe(e.title)}</h3><p style="margin-top:12px">${safe(e.promise||'وعده کارفرما هنوز تدوین نشده است.')}</p><div class="hairline"></div><p class="muted" style="font-size:.85rem">شواهد: ${safe((e.evidence||'ثبت نشده').slice(0,180))}</p><div class="buttons" style="margin-top:17px"><button class="btn secondary small" data-act="edit-evp" data-id="${e.id}">تکمیل / ویرایش</button>${e.outreach?`<button class="btn soft small" data-act="copy-evp" data-id="${e.id}">کپی پیام ارتباطی</button>`:''}</div></div>`).join(''):empty('✦','هنوز EVP ندارید','یک نقش یا گروه هدف انتخاب کنید و وعده کارفرمایی مبتنی بر شواهد بسازید.',nbtn('new-evp','ساخت EVP'))}</div>`}
function sourcingPage(){const src=st.dashboard?.sources||{};const total=st.dashboard?.total||0;return pageHeader('منابع شناسایی و جذب','استعدادهای منفعل را از کانال‌های مناسب و ارتباط‌های قابل اعتماد پیدا کنید.',nbtn('new-referral','＋ ثبت معرفی'))+`<div class="grid two"><section class="panel"><div class="panel-head"><h2>کانال‌های ورودی</h2></div>${total?stageBars(src,total):empty('⌁','هنوز داده‌ای وجود ندارد','با ثبت منبع هر استعداد، اثربخشی کانال‌ها قابل سنجش می‌شود.')}<div class="hairline"></div><p class="muted" style="font-size:.84rem">کانال‌ها: معرفی همکاران، فارغ‌التحصیلان، کارآموزان، دانشگاه، جوامع تخصصی، استعدادیابی و ارتباط مستقیم.</p></section><section class="panel"><div class="panel-head"><h2>معرفی‌های همکاران</h2><span class="chip">${fnum(st.referrals.length)} مورد</span></div>${st.referrals.length?st.referrals.map(r=>`<div class="detail-item"><b>${safe(r.candidate_name)}</b><p class="muted" style="font-size:.85rem">معرف: ${safe(r.referrer)} · ${fdate(r.created_at)}</p><p style="font-size:.85rem">${safe(r.reason)}</p></div>`).join(''):empty('♡','معرفی ثبت نشده','همکاران سازمان می‌توانند افراد مناسب را با توضیح مبنای معرفی پیشنهاد دهند.',nbtn('new-referral','ثبت معرفی'))}</section></div><section class="panel" style="margin-top:18px"><h2>پیش از ارسال پیام به استعداد</h2><p class="sub">✓ تناسب حرفه‌ای روشن باشد · ✓ پیام شخصی‌سازی شود · ✓ اختیار و رضایت فرد محترم شمرده شود · ✓ نتیجه تماس ثبت شود</p></section>`}
function relationshipsPage(){const pending=st.activities.filter(a=>!a.completed).sort((a,b)=>(a.due_date||'9999').localeCompare(b.due_date||'9999'));return pageHeader('برنامه ارتباطات','چرخه Candidate Retention: برنامه‌ریزی، تعامل، مستندسازی و اقدام بعدی',nbtn('new-activity','＋ برنامه ارتباطی'))+`<div class="grid two"><section class="panel"><div class="panel-head"><div><h2>پیگیری‌های باز</h2><p class="sub">با مالک مشخص و تاریخ تعهد</p></div><span class="chip">${fnum(pending.length)} مورد</span></div>${pending.length?pending.map(a=>`<div class="detail-item separate"><div><b>${safe(a.summary)}</b><p class="muted" style="font-size:.82rem">${safe(st.candidates.find(c=>c.id===a.candidate_id)?.full_name||'استعداد حذف‌شده')} · ${dname(a.type)}</p><span class="chip ${a.due_date&&a.due_date<today()?'warn':''}">${fdate(a.due_date)}</span></div><button class="btn small soft" data-act="complete-activity" data-id="${a.id}">✓ انجام شد</button></div>`).join(''):empty('♡','پیگیری بازی ندارید','برنامه‌های ارتباط منظم و شخصی به حفظ رابطه با افراد ارزشمند کمک می‌کند.',nbtn('new-activity','برنامه‌ریزی اقدام'))}</section><section class="panel"><div class="panel-head"><h2>منطق چرخه حفظ نامزد</h2></div><div class="stack">${[['۱','ورود باکیفیت به Talent Pool'],['۲','برنامه تماس متناسب با فرد'],['۳','گفتگو و ارائه ارزش واقعی'],['۴','ثبت تعامل و اقدام بعدی'],['۵','فرصت شغلی متناسب در زمان مناسب']].map(([i,t])=>`<div class="detail-item"><span class="chip dark" style="margin-left:10px">${i}</span>${t}</div>`).join('')}</div><div class="insight" style="margin-top:20px">لیست رزومه بدون اقدام بعدی، Talent Pool زنده نیست. کیفیت رابطه را با تداوم تماس‌ها و تناسب فرصت‌ها ارزیابی کنید.</div></section></div>`}
function experiencePage(){const d=st.dashboard||{};return pageHeader('تجربه نامزد','سه اصل Trost: سرعت، شفافیت و احترام / قدردانی',nbtn('new-survey','＋ ثبت بازخورد'))+`<div class="grid three"><div class="panel metric"><small>سرعت پاسخ‌گویی</small><strong>${d.survey_averages?fnum(d.survey_averages.speed)+'/۵':'—'}</strong></div><div class="panel metric"><small>شفافیت فرایند</small><strong>${d.survey_averages?fnum(d.survey_averages.transparency)+'/۵':'—'}</strong></div><div class="panel metric"><small>احترام و قدردانی</small><strong>${d.survey_averages?fnum(d.survey_averages.appreciation)+'/۵':'—'}</strong></div></div><div class="grid two" style="margin-top:20px"><section class="panel"><h2>رفتارهای قابل مشاهده</h2><div class="stack" style="margin-top:14px"><div class="detail-item"><b>سرعت</b><p class="muted">پاسخ به‌موقع و اطلاع دادن از تأخیر؛ بدون وعده مبهم.</p></div><div class="detail-item"><b>شفافیت</b><p class="muted">مرحله فعلی، مسئول رسیدگی و زمان تقریبی اقدام بعدی.</p></div><div class="detail-item"><b>قدردانی شخصی</b><p class="muted">پاسخ محترمانه، گوش‌دادن و اطلاع‌رسانی حتی در صورت رد پیشنهاد.</p></div></div></section><section class="panel"><h2>حداقل اعتبار برای نمایش میانگین</h2><p style="margin-top:14px">${d.surveys_count?`تا کنون ${fnum(d.surveys_count)} بازخورد ثبت شده است.`:'بازخوردی هنوز ثبت نشده است.'}</p><p class="muted" style="margin-top:10px">برای کاهش امکان شناسایی افراد، شاخص‌های تجمیعی فقط پس از ثبت دست‌کم سه بازخورد نمایش داده می‌شوند.</p></section></div>`}
function reportsPage(){const d=st.dashboard||{total:0,priority_a:0,overdue:0,positions:0};const r=st.roi;const hcva=r.fte>0?(r.revenue-(r.costs-r.hr))/r.fte:null;
 return pageHeader('گزارش‌های مدیریتی','نگاه استراتژیک به رابطه با استعداد و ریسک تأمین نیروی انسانی',`<button class="btn secondary" data-act="export-csv">⬇ خروجی داده‌ها</button>`)+`<div class="grid four"><div class="panel metric"><small>استعدادها</small><strong>${fnum(d.total)}</strong></div><div class="panel metric"><small>اولویت A</small><strong>${fnum(d.priority_a)}</strong></div><div class="panel metric"><small>پیگیری معوق</small><strong>${fnum(d.overdue)}</strong></div><div class="panel metric"><small>نقش‌ها</small><strong>${fnum(d.positions)}</strong></div></div><div class="grid two" style="margin-top:20px"><section class="panel"><h2>توزیع پرونده‌ها</h2><p class="sub">مبنای گزارش: پرونده‌های واقعی ثبت‌شده</p><div style="margin-top:20px">${d.total?stageBars(d.stages,d.total):empty('◈','داده‌ای ثبت نشده','گزارش‌ها پس از ثبت پرونده واقعی ساخته می‌شوند.')}</div></section><section class="panel"><h2>نقش‌های دارای ریسک جذب</h2><p class="sub">تحلیل بر اساس اولویت، کمیابی و تقاضا</p>${st.positions.filter(p=>p.market_availability<=2||p.strategic_importance>=4).length?st.positions.filter(p=>p.market_availability<=2||p.strategic_importance>=4).map(p=>`<div class="detail-item separate"><b>${safe(p.title)}</b><span class="chip">${positionType(p)}</span></div>`).join(''):empty('◉','هنوز نقشی ارزیابی نشده','نقشه نقش‌های حیاتی را تکمیل کنید.')}</section></div><section class="panel" style="margin-top:20px"><div class="panel-head"><div><h2>کاربرگ ارزش افزوده سرمایه انسانی (HCVA)</h2><p class="sub">محاسبه سناریویی با فرض‌های خودتان؛ نتیجه، ROI قطعی TRM نیست.</p></div><span class="chip">Trost · Chapter 9</span></div><div class="grid four">${[['revenue','درآمد سازمان'],['costs','کل هزینه‌ها'],['hr','هزینه‌های منابع انسانی'],['fte','نیروی تمام‌وقت معادل (FTE)']].map(([id,label])=>`<div class="form-group"><label>${label}</label><input id="roi-${id}" type="number" min="0" value="${r[id]}" placeholder="۰"></div>`).join('')}</div><div class="insight">HCVA = [درآمد − (کل هزینه‌ها − هزینه‌های HR)] ÷ FTE. <b>خروجی سناریو: ${hcva===null?'نیازمند داده':fnum(Math.round(hcva))}</b></div><p class="footnote">این برآورد مبتنی بر مدل ارائه‌شده در کتاب است. مقادیر نمونه و ضرایبِ مفروض نباید به‌عنوان شواهد قطعی بهره‌وری یا سودآوری معرفی شوند.</p></section>`}
function settingsPage(){const role=st.me.user.role,admin=['owner','admin'].includes(role);return pageHeader('تنظیمات سازمان','دسترسی اعضا، نصب برنامه و حریم خصوصی',`<button class="btn secondary" data-act="logout">خروج از حساب</button>`)+`<div class="grid two"><section class="panel"><h2>فضای سازمان</h2><div class="detail-item"><div class="label">نام سازمان</div><div class="value">${safe(st.me.org.name)}</div></div><div class="detail-item"><div class="label">حساب فعال</div><div class="value ltr">${safe(st.me.user.email)}</div></div><div class="detail-item"><div class="label">نقش شما</div><div class="value">${dname(st.me.user.role)}</div></div><button class="btn soft" style="margin-top:18px" data-act="install">⬇ نصب روی گوشی یا دسکتاپ</button></section><section class="panel"><div class="panel-head"><h2>اعضای تیم</h2>${admin?nbtn('new-invite','＋ دعوت عضو','','small'):''}</div>${admin?(st.members.length?st.members.map(u=>`<div class="detail-item separate"><div><b>${safe(u.name)}</b><p class="muted ltr" style="font-size:.81rem">${safe(u.email)}</p><span class="chip">${dname(u.role)}</span> ${!u.active?'<span class="chip warn">غیرفعال</span>':''}</div>${u.role!=='owner'&&u.id!==st.me.user.id?`<button class="btn secondary small" data-act="toggle-member" data-id="${u.id}">${u.active?'تعلیق':'فعال‌سازی'}</button>`:''}</div>`).join(''):empty('♟','عضو تیم ثبت نشده','از طریق دعوت‌نامه با همکارانتان همکاری کنید.')):'<p class="muted">مدیریت دسترسی اعضا در اختیار مدیر سازمان است.</p>'}</section></div><div class="grid two" style="margin-top:20px"><section class="panel"><h2>ملاحظات داده و رضایت</h2><p class="muted">فقط اطلاعاتی را ثبت کنید که مبنای قانونی و مجوز پردازش آن را دارید. در پرونده فرد می‌توانید مجوز تماس و درخواست عدم ارتباط را ثبت کنید. خروجی و حذف داده‌ها برای نقش‌های مجاز فراهم است.</p><div class="insight" style="margin-top:17px">اطلاعات نامزدها در حافظه آفلاین گوشی ذخیره نمی‌شود و هر سازمان فضای داده مستقل خود را دارد. ارزیابی حقوقی، توافق‌نامه پردازش داده و سیاست نگهداشت پیش از راه‌اندازی گسترده لازم است.</div></section><section class="panel"><h2>درباره مدل علمی</h2><p style="margin-top:11px"><b>Armin Trost</b> (2014), <em>Talent Relationship Management: Competitive Recruiting Strategies in Times of Talent Shortage</em>, Springer.</p><p class="muted" style="margin-top:12px">مدل راهبردی و منطق فعالیت‌ها با الهام از مباحث Target Groups، EVP، Active Sourcing، Candidate Retention، Candidate Experience و Framework Conditions توسعه یافته است. این محصول، اپلیکیشن رسمی نویسنده یا ناشر نیست.</p><p class="footnote">Version 1.0 · Independent implementation</p></section></div>${admin?`<section class="panel" style="margin-top:20px"><div class="panel-head"><h2>ردپای فعالیت‌ها</h2><span class="chip">آخرین ۱۰۰ رخداد</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>عملیات</th><th>موضوع</th><th>زمان</th></tr></thead><tbody>${st.audit.slice(0,30).map(a=>`<tr><td>${safe(a.action)}</td><td>${safe(a.entity)}</td><td>${fdate(a.created_at)}</td></tr>`).join('')||'<tr><td colspan="3">فعلاً رویدادی ثبت نشده است.</td></tr>'}</tbody></table></div></section>`:''}`}
function renderApp(){document.title=`${NAV.find(n=>n[0]===st.page)?.[1]} | TRM Workspace`;let page={dashboard:dashboardPage,candidates:candidatesPage,positions:positionsPage,groups:groupsPage,evp:evpPage,sourcing:sourcingPage,relationships:relationshipsPage,experience:experiencePage,reports:reportsPage,settings:settingsPage}[st.page]||dashboardPage;
 node.innerHTML=`<div class="shell">${appSidebar()}<div class="workspace">${topbar()}<main class="content">${page()}</main></div>${mobileNav()}</div>`;
}
async function loadData(){const [c,p,g,e,a,r,d]=await Promise.all([api('/candidates'),api('/positions'),api('/target-groups'),api('/evps'),api('/activities'),api('/referrals'),api('/dashboard')]);Object.assign(st,{candidates:c,positions:p,groups:g,evps:e,activities:a,referrals:r,dashboard:d});if(st.page==='settings'&&['owner','admin'].includes(st.me.user.role))await loadAdmin()}
async function loadAdmin(){const [members,audit]=await Promise.all([api('/members'),api('/audit')]);st.members=members;st.audit=audit}
async function refresh(){await loadData();renderApp()}
async function goto(page){if(!st.me)return;st.page=page;st.query='';st.stage='';st.priority='';window.scrollTo({top:0,behavior:'instant'});if(page==='settings'&&['owner','admin'].includes(st.me.user.role)){try{await loadAdmin()}catch(e){toast(e.message,'error')}}renderApp();history.replaceState(null,'','#'+page)}
function positionOptions(){return st.positions.map(p=>[p.id,p.title])}
function groupOptions(){return st.groups.map(g=>[g.id,g.name])}
function userOptions(){return st.members.map(u=>[u.id,u.name])}
function candidateForm(c){const isEdit=!!c;const v=c||{};return `<form data-form="candidate" ${isEdit?`data-id="${c.id}"`:''}>${field('نام و نام خانوادگی *','full_name',v.full_name,'text','required minlength="2"')}<div class="form-row">${field('عنوان شغلی','current_title',v.current_title)}${field('شرکت فعلی','company',v.company)}</div><div class="form-row">${field('ایمیل','email',v.email,'email')}${field('شماره تماس','phone',v.phone,'tel')}</div><div class="form-row">${field('شهر','city',v.city)}${selectField('منبع شناسایی','source',v.source||'direct',['direct','referral','alumni','internship','campus','community','scouting','event','other'],'')}</div>${field('مهارت‌ها (با ویرگول جدا کنید)','skills',v.skills)}${field('علاقه‌مندی‌های شغلی','interests',v.interests)}<div class="form-row three">${selectField('مرحله رابطه','stage',v.stage||'identified',['identified','contacted','interested','nurturing','opportunity','selection','hired','declined','archived'],'')}${selectField('اولویت بر مبنای شواهد','priority',v.priority||'B',[['A','A · اولویت بالا'],['B','B · اولویت میانی'],['C','C · اولویت پایین']],'')}${selectField('آمادگی برای فرصت','readiness',v.readiness||'unknown',[['unknown','نامشخص'],['open','آماده گفتگو'],['later','برای آینده'],['unavailable','فعلاً آماده نیست']],'')}</div>${area('دلیل اولویت (شواهد حرفه‌ای)','priority_reason',v.priority_reason,'به‌جای قضاوت‌های کلی، به تجربه و نمونه عملکرد مرتبط با نقش اشاره کنید.')}<div class="form-row">${selectField('نقش هدف','position_id',v.position_id||'',positionOptions())}${selectField('گروه هدف','target_group_id',v.target_group_id||'',groupOptions())}</div><div class="form-row">${selectField('وضعیت مجوز تماس','consent',v.consent||'unknown',[['unknown','تأیید نشده'],['granted','مجوز ثبت شده'],['revoked','مجوز لغو شده']],'')}${field('تاریخ مجوز','consent_date',v.consent_date||'','date')}</div>${field('منبع مجوز / یادداشت رضایت','consent_source',v.consent_source)}${field('پیگیری بعدی','next_followup',v.next_followup||'','date')}${area('یادداشت حرفه‌ای','notes',v.notes)}<div class="form-group"><label><input type="checkbox" name="do_not_contact" ${v.do_not_contact?'checked':''} style="width:auto;min-height:0;margin-left:8px">عدم تماس با فرد / Opt-out</label></div>${formFooter(isEdit?'ذخیره تغییرات':'ثبت استعداد')}</form>`}
function positionForm(p){const v=p||{};return `<form data-form="position" ${p?`data-id="${p.id}"`:''}>${field('عنوان نقش *','title',v.title,'text','required minlength="2"')}${field('واحد سازمانی','department',v.department)}<div class="form-row">${selectField('اهمیت راهبردی','strategic_importance',v.strategic_importance||3,[1,2,3,4,5].map(n=>[n,n+' از ۵']),'')}${selectField('دسترسی به استعداد در بازار','market_availability',v.market_availability||3,[1,2,3,4,5].map(n=>[n,n+' از ۵ '+(n===1?'· بسیار کمیاب':n===5?'· فراوان':'')]),'')}</div><div class="form-row three">${field('تقاضای ۱۲ ماه آتی (نفر)','future_demand',v.future_demand??0,'number','min="0"')}${field('تعداد فعلی افراد','current_headcount',v.current_headcount??0,'number','min="0"')}${field('پوشش از داخل سازمان','internal_pipeline',v.internal_pipeline??0,'number','min="0"')}</div><div class="form-row three">${field('رشد سالانه (%)','annual_growth_pct',v.annual_growth_pct??0,'number','step="0.1"')}${field('نرخ خروج (%)','annual_turnover_pct',v.annual_turnover_pct??0,'number','step="0.1" min="0"')}${field('بازنشستگی مورد انتظار','expected_retirements',v.expected_retirements??0,'number','min="0"')}</div>${area('چالش‌های حیاتی این نقش','challenges',v.challenges,'در چه موقعیت‌های دشواری عملکرد افراد برتر تفاوت معنادار ایجاد می‌کند؟')}${area('شکاف‌های مهارتی آموزش‌پذیر','trainable_gaps',v.trainable_gaps,'الزامات روز اول را از مهارت‌هایی که قابل توسعه هستند جدا کنید.')}${area('یادداشت راهبردی','notes',v.notes)}${formFooter(p?'ذخیره نقش':'تعریف نقش')}</form>`}
function groupForm(g){const v=g||{};return `<form data-form="group" ${g?`data-id="${g.id}"`:''}>${field('نام گروه هدف','name',v.name,'text','required minlength="2"')}${selectField('نقش مرتبط','position_id',v.position_id||'',positionOptions())}${area('ویژگی‌ها، تجربه و توانمندی‌ها','traits',v.traits)}${area('خواسته‌ها و ترجیحات شغلی','preferences',v.preferences)}${area('کانال‌های حرفه‌ای ارتباط','channels',v.channels)}${formFooter(g?'ثبت تغییرات':'ثبت گروه هدف')}</form>`}
function evpForm(e){const v=e||{};return `<form data-form="evp" ${e?`data-id="${e.id}"`:''}>${field('عنوان طرح EVP','title',v.title,'text','required minlength="2"')}<div class="form-row">${selectField('نقش هدف','position_id',v.position_id||'',positionOptions())}${selectField('گروه هدف','target_group_id',v.target_group_id||'',groupOptions())}</div>${area('۱. قوت‌های واقعی ما','strengths',v.strengths,'چه چیز واقعاً درباره این نقش/سازمان درست است؟')}${area('۲. ترجیحات گروه هدف','preferences',v.preferences,'این افراد واقعاً چه می‌خواهند؟')}${area('۳. تفاوت با کارفرمایان رقیب','differentiation',v.differentiation,'کدام مزیت قابل دفاع و غیرقابل جایگزینی است؟')}${area('۴. داستان‌ها و شواهد واقعی','evidence',v.evidence,'یک Signature Experience ملموس و قابل‌راستی‌آزمایی بنویسید.')}${area('۵. وعده مشخص کارفرما (EVP)','promise',v.promise)}${area('۶. پیام شخصی‌سازی‌شده ارتباط اولیه','outreach',v.outreach)}${formFooter(e?'ذخیره EVP':'ثبت EVP')}</form>`}
function activityForm(preselected){const opts=st.candidates.filter(c=>!c.archived).map(c=>[c.id,c.full_name]);return `<form data-form="activity">${selectField('استعداد مرتبط','candidate_id',preselected||'',opts)}${selectField('نوع تعامل','type','followup',[['followup','پیگیری'],['call','تماس تلفنی'],['email','ایمیل'],['meeting','جلسه'],['event','دعوت به رویداد'],['note','یادداشت'],['referral','معرفی'],['selection','ارزیابی']],'')}${field('عنوان اقدام','summary','','text','required minlength="2"')}${field('تاریخ اقدام','due_date',today(),'date')}${area('نتیجه مورد انتظار / جزئیات','details')}${formFooter('برنامه‌ریزی اقدام')}</form>`}
function referralForm(){return `<form data-form="referral">${field('نام فرد معرفی‌شده *','candidate_name','','text','required')}${field('نام معرفی‌کننده *','referrer','','text','required')}${field('اطلاعات تماس (با مجوز)','candidate_contact')}${area('علت تناسب حرفه‌ای','reason')}${formFooter('ثبت معرفی')}</form>`}
function surveyForm(){return `<form data-form="survey">${selectField('استعداد مرتبط','candidate_id','',st.candidates.map(c=>[c.id,c.full_name]))}<p class="sub" style="margin-bottom:15px">مقادیر از ۱ (بسیار ضعیف) تا ۵ (بسیار خوب)</p>${[['speed','سرعت پاسخ‌گویی'],['transparency','شفافیت فرایند'],['appreciation','احترام و قدردانی']].map(([id,label])=>selectField(label,id,4,[1,2,3,4,5].map(v=>[v,v+' از ۵']),'')).join('')}${area('بازخورد کوتاه و اختیاری','feedback')}${formFooter('ثبت بازخورد')}</form>`}
function displayCandidate(id){const c=st.candidates.find(c=>c.id===id);if(!c)return toast('پرونده پیدا نشد.','error');st.selectedCandidate=id;
 const acts=st.activities.filter(a=>a.candidate_id===id).sort((a,b)=>b.created_at.localeCompare(a.created_at));
 const related=[['عنوان شغلی',c.current_title],['سازمان',c.company],['ایمیل',c.email],['تلفن',c.phone],['شهر',c.city],['منبع',dname(c.source)],['وضعیت رابطه',dname(c.stage)],['تمایل به فرصت',dname(c.readiness)],['اجازه تماس',dname(c.consent)],['تاریخ اجازه',c.consent_date?fdate(c.consent_date):'—'],['شواهد اولویت',c.priority_reason],['مهارت‌ها',c.skills],['علاقه‌مندی‌ها',c.interests],['یادداشت‌ها',c.notes]];
 const inner=`<div class="candidate-banner"><div class="avatar">${safe(c.full_name.slice(0,1))}</div><div style="flex:1"><h2>${safe(c.full_name)}</h2><p class="muted">${safe(c.current_title)} ${c.company?'· '+safe(c.company):''}</p><div class="shelf"><span class="chip ${c.priority.toLowerCase()}">اولویت ${c.priority}</span><span class="chip">${dname(c.stage)}</span>${c.do_not_contact?'<span class="chip warn">عدم تماس</span>':''}</div></div></div><div class="buttons" style="margin:20px 0"><button class="btn small" data-act="activity-for" data-id="${c.id}">＋ برنامه ارتباط</button><button class="btn secondary small" data-act="edit-candidate" data-id="${c.id}">✎ ویرایش</button>${['owner','admin'].includes(st.me.user.role)?`<button class="btn danger small" data-act="delete-candidate" data-id="${c.id}">حذف</button>`:''}</div><div class="tabs"><button class="selected" data-act="candidate-tab" data-target="profile">پرونده</button><button data-act="candidate-tab" data-target="activities">تاریخچه تعامل (${fnum(acts.length)})</button></div><div id="candidate-tabs-content" data-id="${c.id}">${candidateDetailTab('profile',c,acts,related)}</div>`;
 openModal('پرونده استعداد',inner);
}
function candidateDetailTab(tab,c,acts,related){if(tab==='profile')return `<div class="grid two">${related.map(([l,v])=>`<div class="detail-item"><div class="label">${l}</div><div class="value">${safe(v||'—')}</div></div>`).join('')}</div>`;return acts.length?`<div class="timeline">${acts.map(a=>`<div class="timeline-event"><div class="separate"><b>${safe(a.summary)}</b><span class="chip ${a.completed?'a':''}">${a.completed?'انجام‌شده':'باز'}</span></div><p>${dname(a.type)} · ${fdate(a.due_date||a.created_at)}</p><p>${safe(a.details)}</p></div>`).join('')}</div>`:empty('♡','گفتگویی ثبت نشده','اولین تماس، جلسه یا یادداشت ارتباطی این استعداد را ثبت کنید.',nbtn('activity-for','＋ ثبت ارتباط',c.id))}
function modalFor(act,id){switch(act){case'new-candidate':return openModal('افزودن استعداد',candidateForm());case'edit-candidate':return openModal('ویرایش پرونده',candidateForm(st.candidates.find(c=>c.id===id)));case'new-position':return openModal('تعریف نقش حیاتی',positionForm());case'edit-position':return openModal('ویرایش نقش و محاسبه تقاضا',positionForm(st.positions.find(p=>p.id===id)));case'new-group':return openModal('گروه هدف جدید',groupForm());case'edit-group':return openModal('ویرایش گروه هدف',groupForm(st.groups.find(g=>g.id===id)));case'new-evp':return openModal('طراحی EVP اختصاصی',evpForm());case'edit-evp':return openModal('ویرایش EVP',evpForm(st.evps.find(e=>e.id===id)));case'new-activity':case'activity-for':return openModal('برنامه ارتباطی جدید',activityForm(id),'');case'new-referral':return openModal('معرفی استعداد',referralForm());case'new-survey':return openModal('بازخورد تجربه نامزد',surveyForm());case'new-invite':return openModal('دعوت عضو سازمان',`<form data-form="invite">${field('ایمیل همکار','email','','email','required')}${selectField('نقش','role','recruiter',[['admin','مدیر سازمان'],['recruiter','کارشناس جذب'],['manager','مدیر صف'],['viewer','فقط مشاهده']],'')}${formFooter('ساخت لینک دعوت')}</form>`,{narrow:true});}}
function installDialog(){openModal('نصب مستقل TRM Workspace',`<p>این نرم‌افزار یک <b>Progressive Web App</b> است و پس از انتشار روی نشانی امن (HTTPS)، مثل یک اپ مستقل از صفحه اصلی دستگاه اجرا می‌شود.</p><div class="detail-item"><b>Android / Chrome</b><p class="muted">منوی مرورگر ⋮ ← «Install app» یا «افزودن به صفحه اصلی».</p></div><div class="detail-item"><b>iPhone / Safari</b><p class="muted">Share ← Add to Home Screen ← Add.</p></div><div class="detail-item"><b>Desktop / Chrome / Edge</b><p class="muted">روی آیکون Install در نوار آدرس کلیک کنید.</p></div><div class="install-tip">این اپ دارای هویت و محدوده نصب مستقل از سایر اپلیکیشن‌های شماست. اطلاعات حساس به‌صورت آفلاین ذخیره نمی‌شوند.</div><div class="modal-footer"><button class="btn" data-act="close-modal">متوجه شدم</button></div>`,{narrow:true})}
async function handleAction(act,id,target){switch(act){
case'close-modal':closeModal();return;
case'switch-auth':renderPublic(target||'landing');return;
case'view-candidate':displayCandidate(id);return;
case'candidate-tab':{const c=st.candidates.find(c=>c.id===st.selectedCandidate),acts=st.activities.filter(a=>a.candidate_id===st.selectedCandidate);if(!c)return;const labels=[['عنوان شغلی',c.current_title],['سازمان',c.company],['ایمیل',c.email],['تلفن',c.phone],['شهر',c.city],['منبع',dname(c.source)],['وضعیت رابطه',dname(c.stage)],['اجازه تماس',dname(c.consent)],['مهارت‌ها',c.skills],['شواهد اولویت',c.priority_reason],['یادداشت‌ها',c.notes]];$('#candidate-tabs-content').innerHTML=candidateDetailTab(target,c,acts,labels);$$('.tabs button').forEach(b=>b.classList.toggle('selected',b.dataset.target===target));return}
case'install':if(st.installPrompt){try{st.installPrompt.prompt();const choice=await st.installPrompt.userChoice;if(choice?.outcome==='accepted')toast('درخواست نصب به مرورگر ارسال شد.');st.installPrompt=null}catch{installDialog()}}else installDialog();return;
case'logout':await api('/auth/logout','POST');st.me=null;renderPublic();history.replaceState(null,'','/');return;
case'export-csv':{const res=await fetch('/api/candidates-export');if(!res.ok)throw Error('اجازه خروجی گرفتن ندارید.');const blob=await res.blob();const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download='trm-candidates.csv';a.click();URL.revokeObjectURL(u);toast('فایل CSV آماده شد.');return}
case'import-csv':return openModal('ورود پرونده‌ها از CSV',`<p class="muted" style="margin-bottom:16px">فایل CSV با ستون <code>full_name</code> و سایر ستون‌های خروجی TRM Workspace قابل ورود است. ایمیل‌های تکراری وارد نمی‌شوند. حداکثر ۵۰۰ ردیف در هر بار.</p><form data-form="import"><div class="form-group"><label>انتخاب فایل CSV</label><input type="file" name="file" accept=".csv,text/csv" required></div>${formFooter('ورود داده')}</form>`,{narrow:true});
case'copy-evp':{let e=st.evps.find(e=>e.id===id);await navigator.clipboard.writeText(e.outreach||'');toast('پیام ارتباطی کپی شد؛ هیچ پیامی به‌صورت خودکار ارسال نشده است.');return}
case'complete-activity':await api('/activities/'+encodeURIComponent(id)+'/complete','PATCH');toast('اقدام تکمیل شد.');await refresh();return;
case'toggle-member':await api('/members/'+encodeURIComponent(id)+'/toggle','PATCH');toast('وضعیت دسترسی عضو تغییر کرد.');await refresh();return;
case'delete-candidate':if(!confirm('پرونده و تاریخچه تعامل این استعداد به‌طور دائمی حذف شود؟'))return;await api('/candidates/'+encodeURIComponent(id),'DELETE');closeModal();toast('پرونده حذف شد.');await refresh();return;
default:modalFor(act,id);return;
}}
function parseForm(form){const obj=Object.fromEntries(new FormData(form).entries());for(const name of ['strategic_importance','market_availability','future_demand','current_headcount','annual_growth_pct','annual_turnover_pct','expected_retirements','internal_pipeline','speed','transparency','appreciation'])if(name in obj)obj[name]=Number(obj[name]);if(form.dataset.form==='candidate'){obj.do_not_contact=!!form.elements.do_not_contact?.checked;obj.position_id=obj.position_id||null;obj.target_group_id=obj.target_group_id||null;obj.owner_id=null;}if(form.dataset.form==='position'){ }if(form.dataset.form==='group'||form.dataset.form==='evp'){obj.position_id=obj.position_id||null;if('target_group_id'in obj)obj.target_group_id=obj.target_group_id||null}return obj}
async function submitForm(form){const kind=form.dataset.form;if(kind==='import'){const file=form.elements.file?.files?.[0];if(!file)throw new Error('فایل انتخاب نشده است.');const res=await fetch('/api/candidates-import',{method:'POST',body:await file.arrayBuffer()});const data=await res.json();if(!res.ok)throw new Error(data.detail||'ورود داده ناموفق بود');closeModal();toast(`${fnum(data.imported)} پرونده وارد شد؛ ${fnum(data.skipped)} ردیف کنار گذاشته شد.`);return refresh()}
 const data=parseForm(form);let endpoint='',method='POST';if(['candidate','position','group','evp'].includes(kind)){const resource={candidate:'candidates',position:'positions',group:'target-groups',evp:'evps'}[kind];endpoint='/'+resource;if(form.dataset.id){endpoint+='/'+form.dataset.id;method='PUT'}}else if(kind==='activity')endpoint='/activities';else if(kind==='referral')endpoint='/referrals';else if(kind==='survey')endpoint='/surveys';else if(kind==='invite')endpoint='/invites';else if(kind==='register')endpoint='/auth/register';else if(kind==='login')endpoint='/auth/login';else if(kind==='accept-invite')endpoint='/invites/accept';else throw new Error('فرم ناشناخته است.');
 const result=await api(endpoint,method,data);
 if(kind==='invite'){const link=location.origin+'/?invite='+encodeURIComponent(result.code);closeModal();openModal('لینک دعوت آماده است',`<p>این لینک فقط هفت روز معتبر است و فقط برای ایمیل <span class="ltr">${safe(result.email)}</span> ایجاد شده است.</p><div class="form-group"><label>لینک اختصاصی دعوت</label><input id="invite-link" readonly dir="ltr" value="${safe(link)}"></div><button class="btn" data-act="copy-invite">کپی لینک</button>`,{narrow:true});return}
 if(['register','login','accept-invite'].includes(kind)){closeModal();history.replaceState(null,'','/');st.me=await api('/me');st.page='dashboard';await loadData();renderApp();toast('به فضای کار خوش آمدید.');return}
 closeModal();toast('اطلاعات با موفقیت ذخیره شد.');await refresh();}
// All interaction is delegated to survive re-rendering.
document.addEventListener('click',async event=>{
 const el=event.target.closest('[data-act],[data-nav]');if(!el)return;
 if(el.tagName==='A')event.preventDefault();
 if(el.dataset.nav){try{await goto(el.dataset.nav)}catch(e){toast(e.message,'error')}return}
 if(el.dataset.act==='copy-invite'){try{await navigator.clipboard.writeText($('#invite-link').value);toast('لینک کپی شد.')}catch{toast('لینک را از کادر کپی کنید.','error')}return}
 try{await handleAction(el.dataset.act,el.dataset.id||'',el.dataset.target||'')}catch(e){toast(e.message||'خطای غیرمنتظره','error')}
});
document.addEventListener('submit',async event=>{const form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();const btn=form.querySelector('button[type=submit]');if(btn)btn.disabled=true;try{await submitForm(form)}catch(e){toast(e.message||'ثبت اطلاعات ناموفق بود','error')}finally{if(btn)btn.disabled=false}});
document.addEventListener('change',event=>{if(event.target.id==='filter-stage'){st.stage=event.target.value;renderApp()}if(event.target.id==='filter-priority'){st.priority=event.target.value;renderApp()}if(event.target.id?.startsWith('roi-')){let field=event.target.id.slice(4);st.roi[field]=Number(event.target.value)||0;renderApp()}});
let searchTimer;document.addEventListener('input',event=>{if(event.target.id==='candidate-search'){st.query=event.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const box=$('#candidate-records');if(!box)return;const matches=st.candidates.filter(c=>!c.archived&&(!st.query||[c.full_name,c.current_title,c.company,c.skills].some(x=>String(x||'').toLocaleLowerCase().includes(st.query.toLocaleLowerCase())))&&(!st.stage||c.stage===st.stage)&&(!st.priority||c.priority===st.priority));box.innerHTML=matches.length?matches.map(candidateRow).join(''):empty('♟','موردی پیدا نشد','عبارت جست‌وجو را تغییر دهید.');},180)}});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeModal();if(event.key==='Enter'&&event.target.matches('[role="button"][data-nav]'))goto(event.target.dataset.nav)});
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();st.installPrompt=event});
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('/sw.js').catch(()=>{}));
(async()=>{try{st.me=await api('/me');let wanted=location.hash.slice(1);st.page=NAV.find(x=>x[0]===wanted)?wanted:'dashboard';await loadData();renderApp()}catch(e){st.me=null;if(e.status===401){renderPublic();return}node.innerHTML='<main style="max-width:590px;margin:12vh auto;padding:30px;line-height:2"><h1>اتصال به سرور برقرار نشد</h1><p>برای استفاده از TRM Workspace باید نسخه آنلاین و پایگاه داده آن فعال باشد. فایل‌های سورس به‌تنهایی قابل استفاده سازمانی نیستند.</p><p class="muted">'+safe(e.message||'خطای ناشناخته')+'</p><button class="btn" onclick="location.reload()">تلاش دوباره</button></main>'}})();